WITH "__duckstream_0" AS (SELECT CAST((t.c0 + CAST(2 AS INTEGER)) AS INTEGER) AS c0, CAST((t.c0 - CAST(3 AS INTEGER)) AS INTEGER) AS c1, CAST((t.c0 * CAST(4 AS INTEGER)) AS INTEGER) AS c2, CAST((t.c1 + CAST(1 AS BIGINT)) AS BIGINT) AS c3, CAST((t.c2 + CAST(0.125 AS DOUBLE)) AS DOUBLE) AS c4, CAST(t.c0 AS DOUBLE) AS c5 FROM (SELECT "i" AS c0, "n" AS c1, "d" AS c2 FROM "numbers") t)
SELECT CAST(result.c0 AS INTEGER) AS "added", CAST(result.c1 AS INTEGER) AS "subtracted", CAST(result.c2 AS INTEGER) AS "multiplied", CAST(result.c3 AS BIGINT) AS "exact_plus", CAST(result.c4 AS DOUBLE) AS "fractional", CAST(result.c5 AS DOUBLE) AS "floating" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5 FROM "__duckstream_0" v) result;
